"""Offline HTML and Markdown from measured v0.4 records."""
import html,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from homevoice.paths import ROOT,CODE_ROOT
from homevoice.catalog import SCENES
def read(p):return json.loads((ROOT/p).read_text('utf-8'))
summary=read('reports/summary.json');tools=read('spec/sandbox.json');cases=read('reports/case_overview.json');scenes=read('reports/scene_overview.json')
data={'summary':summary,'scenes':scenes,'tools':tools,'cases':cases}
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HomeVoiceBench-ZH v0.4</title><style>
:root{--ink:#203735;--sub:#5a6c69;--accent:#286b60;--paper:#f5f7f3;--line:#d8e2dc;--gold:#ad8241}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 system-ui,'Microsoft YaHei',sans-serif}nav{border-bottom:1px solid var(--line);padding:18px max(24px,calc((100vw - 1180px)/2));display:flex;justify-content:space-between;background:white}a{color:var(--accent)}main{max-width:1180px;margin:auto;padding:45px 24px 80px}header{max-width:900px}h1{font-size:42px;line-height:1.25;margin:14px 0}h2{font-size:26px;margin:48px 0 16px}h3{margin:4px 0}p{color:var(--sub)}small,.muted{color:var(--sub)}.tag{color:var(--accent);font-size:13px;letter-spacing:.08em}.stats,.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:26px 0}.stats article,.card{padding:22px;background:white;border:1px solid var(--line);border-radius:12px}.stats strong{display:block;font-size:32px}.grid{grid-template-columns:repeat(3,1fr)}.card p{font-size:14px;margin-bottom:0}.flow{display:grid;grid-template-columns:1fr 2fr 1fr;gap:24px;align-items:center}.lane{border-left:4px solid var(--accent);padding:15px 20px;background:white;margin:10px 0}.lane:nth-child(2){border-color:#5e7c9c}.lane:nth-child(3){border-color:var(--gold)}.arrow{font-size:12px;color:var(--sub)}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.step{padding:20px;background:white;border-top:4px solid var(--accent)}.step strong{display:block;margin-bottom:10px}.step p{font-size:14px}.scroller{overflow:auto;background:white;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:13px 16px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{background:#eaf0eb}.wrap{white-space:normal;min-width:280px}.controls{display:flex;gap:12px;margin:18px 0;align-items:center;flex-wrap:wrap}select,input{padding:11px;border:1px solid var(--line);border-radius:6px;color:var(--ink);background:white;font:inherit}input{flex:1;min-width:180px}button{font:inherit;cursor:pointer}details{margin:10px 0;border:1px solid var(--line);border-radius:8px;background:white}summary{padding:15px;cursor:pointer}details>div{padding:0 18px 18px}.bar{height:12px;border-radius:8px;overflow:hidden;display:flex;margin:12px 0}.bar i{display:block}.note{padding:18px 22px;border-left:3px solid var(--gold);background:#fbf5e9;color:#665533}.links{display:flex;gap:22px;flex-wrap:wrap;margin-top:25px}.footer{margin-top:48px;border-top:1px solid var(--line);padding-top:22px;font-size:14px}code{font-size:13px} @media(max-width:780px){h1{font-size:31px}.stats,.steps{grid-template-columns:repeat(2,1fr)}.grid,.flow{grid-template-columns:1fr}main{padding-top:28px}nav{gap:20px;font-size:13px}}
</style></head><body><nav><strong>HomeVoiceBench-ZH</strong><a href="https://github.com/09osd09osd/HomeVoiceBench-ZH">代码、数据与复现说明</a></nav><main>
<header><div class="tag">VERSION 0.4 · AUDIO INPUT · HOUSEHOLD INTERACTION</div><h1>家庭语音交互能力测评</h1><p>用真实声音输入，让模型聊天或操作虚拟家庭。观察它能完成什么任务、如何处理更正，以及在哪里开始出错。</p><div class="links"><a href="http://127.0.0.1:18788/review/?dataset=benchmark">打开本地逐题试听页</a><a href="../benchmark/outputs/homevoicebench-v040/HomeVoiceBench-ZH-v0.4.xlsx">下载 Excel 总览</a><a href="../../../docs/index.html">查看保留的 v0.3</a></div></header>
<div class="stats" id="stats"></div>
<h2>一段用户语音，进入三条链路</h2><div class="flow"><article class="card"><h3>相同用户录音</h3><p>DeepSeek 官方 API 生成口语台词 → qwen-audio-3.1-tts-next 合成 → 听音质检。</p><small>原稿保存在数据集中，实验组看不到原稿。</small></article><div><div class="lane"><strong>实验组</strong><br>用户声音 → EdgeInstant-Omni-2B → 原生声音</div><div class="lane"><strong>2B 级联</strong><br>用户声音 → Qwen3-ASR → Qwen3.5-2B → Qwen3-TTS</div><div class="lane"><strong>4B 级联</strong><br>用户声音 → Qwen3-ASR → Qwen3.5-4B → Qwen3-TTS</div></div><article class="card"><h3>程序与听音判官</h3><p>程序检查实际状态和每次写入。Qwen3.8-Omni-Flash 听取用户与助手声音，评价语义和声音质量。</p><small>三组内容决策 greedy；判官温度为 0。</small></article></div>
<h2>任务通过和回答质量分别看</h2><div class="grid"><article class="card"><h3>客观状态与授权</h3><p>灯是否打开、亮度是否正确、提醒时间是否等价、有没有动错设备。先改错再恢复仍会被检查出来。</p></article><article class="card"><h3>声音中的实际回答</h3><p>用户问温度，必须真的说出读数。独立 ASR 与判官听写辅助核对数字；有分歧按固定协议重新听原音频。</p></article><article class="card"><h3>六维质量分</h3><p>表达自然、语气、清晰度和效率照常评分。轻微啰嗦不再自动把一项已完成的任务判失败。</p></article></div>
<div class="note">例：用户说“把灯打开到 20%”。程序核对开关、亮度和未授权写入；听音判官核对有没有虚报执行。说“灯已打开，亮度二十”可以通过，不能要求逐字照读参考答案。</div>
<h2>40% 的题采用逐步加难的成组设计</h2><p>每个正式场景有 2 组，每组 4 题。组内共享初始环境和前缀录音，每题从初始环境独立运行。下面是风扇场景的示意。</p><div class="steps"><article class="step"><strong>第 1 级 · 1 轮</strong><p>打开书房风扇，调到二档。</p><small>明确目标与参数</small></article><article class="step"><strong>第 2 级 · 2 轮</strong><p>保留上一题输入，再说“把它改成三档”。</p><small>追踪对象与新要求</small></article><article class="step"><strong>第 3 级 · 3 轮</strong><p>再说“只关掉它，风速档位保持不变”。</p><small>保留未要求改变的字段</small></article><article class="step"><strong>第 4 级 · 4–5 轮</strong><p>继续要求重新打开或查询，沿用实际上下文。</p><small>持续遵守前面约束</small></article></div><p>基础 60%、标准 30%、挑战 10%。这些是预设难度标签，实际难度与模型能力边界需要结合测评结果看。首次失败级别不是普适的能力上限。</p>
<h2>实测结果</h2><p id="status"></p><div class="scroller"><table><thead><tr><th>系统</th><th>类别</th><th>已判定 / 计划</th><th>任务通过</th><th>通过率</th><th>六维均分 / 5</th></tr></thead><tbody id="results"></tbody></table></div>
<h2>初判、语义复核与听音裁定</h2><p>语义复核依据实际听写和工具证据；初判与复核冲突、或数字需核验时，再盲化重听原音频。采用首个结构有效的裁定，客观规则失败不能被覆盖。各阶段来自同一模型，尚未经过独立人工校准。</p><div id="review-status" class="note"></div><h2>50 个家庭场景</h2><div class="controls"><select id="category" aria-label="类别"><option value="all">全部类别</option><option value="tool">工具调用</option><option value="chat">聊天</option></select><input id="search" placeholder="搜索场景名称或编号" aria-label="搜索场景"></div><div id="scenes"></div>
<h2>精简后的工具沙箱</h2><p>10 个常用工具始终可用；异步任务场景增加 task_get 和 task_cancel。所有工具只操作题目里的虚拟家庭，不连接真实设备。</p><div class="scroller"><table><thead><tr><th>工具</th><th>层级</th><th>用途</th></tr></thead><tbody id="tools"></tbody></table></div>
<h2>如何理解这次测评</h2><div class="grid"><article class="card"><h3>先用 100 题验流程</h3><p>覆盖全部场景、三个难度及完整题组。验证评分与并发后，再运行正式 1000 题。不会为了达到目标通过率而筛选答案。</p></article><article class="card"><h3>中断也留证据</h3><p>试听页显示具体原因、已经执行的调用、未执行的请求和未朗读文字。没有完成音频的轮次不能当作已经说出了答案。</p></article><article class="card"><h3>保留解释范围</h3><p>合成普通话、单 seed、单听音判官，未做正式人评校准。不同系统的部署精度和输出预算不同。结果反映本次完整系统配置。</p></article></div><p class="footer">v0.3 的数据与成绩原样保留。v0.4 改变了题目分布、工具接口和解码配置，新旧分数不能直接解释为模型进步。组内相关性通过按场景聚类的配对区间处理。开发与正式集采用不同题号及题组，但共享场景模板。</p>
</main><script>const DATA=__DATA__;const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const labels={edge_native:'实验组 EdgeInstant',qwen35_2b:'Qwen 2B 级联',qwen35_4b:'Qwen 4B 级联',all:'全部',tool:'工具',chat:'聊天'};const pc=x=>x==null?'尚未完成':(x*100).toFixed(1)+'%';const S=DATA.summary;
document.getElementById('stats').innerHTML=[[S.dataset.cases,'当前数据集题数'],[S.dataset.scenes,'家庭场景'],[3,'参测系统'],['40%','成组题占比']].map(([n,t])=>`<article><strong>${n}</strong>${t}</article>`).join('');
document.getElementById('status').textContent=(S.split==='development'?'开发验证集':'正式测试集')+' · '+(S.evaluation_status==='complete'?'全部题已判定':S.evaluation_status==='needs_semantic_adjudication'?'推理与评分已完成，存在评分分歧，待裁定':'测评进行中，未判定项保持为空')+'。质量均分保留首次听音评分，只覆盖有实际声音评分的题。';
document.getElementById('results').innerHTML=S.systems.map(r=>`<tr><td>${labels[r.system_id]}</td><td>${labels[r.category]}</td><td>${r.decided_count} / ${r.planned}</td><td>${r.passed_count}</td><td>${pc(r.strict_pass_rate)}</td><td>${r.overall_dimension_mean==null?'NA':r.overall_dimension_mean.toFixed(2)}</td></tr>`).join('');
document.getElementById('review-status').innerHTML=(S.semantic_consistency_review?.systems??[]).map(r=>`<p>${labels[r.system_id]}：初判通过 ${r.primary_passed}，复核候选通过 ${r.review_proposed_passed}，曾有分歧 ${r.disputed}，重新听音裁定 ${r.audio_adjudicated??0}，最终通过 ${r.final_passed??r.agreed_passed}，待定 ${r.unresolved_disputes??r.disputed}。</p>`).join('');
function show(){const cat=document.getElementById('category').value,q=document.getElementById('search').value.toLowerCase();document.getElementById('scenes').innerHTML=DATA.scenes.filter(s=>(cat==='all'||s.category===cat)&&(s.scene_id+s.title).toLowerCase().includes(q)).map(s=>`<details><summary><strong>${s.scene_id} · ${E(s.title)}</strong>　${s.case_count} 题</summary><div><p>${E(s.focus??s.family)}</p>${DATA.cases.filter(c=>c.scene_id===s.scene_id).map(c=>`<p><code>${c.case_id}</code> · ${c.turn_count} 轮 · ${E(c.title)}<br><small>${E(c.user_texts[0])}</small></p>`).join('')}</div></details>`).join('');}document.getElementById('category').addEventListener('change',show);document.getElementById('search').addEventListener('input',show);show();
document.getElementById('tools').innerHTML=DATA.tools.tools.map(t=>`<tr><td><code>${t.name}</code></td><td>${DATA.tools.core_tool_names.includes(t.name)?'常用':'异步扩展'}</td><td class="wrap">${E(t.description)}</td></tr>`).join('');</script></body></html>'''
folder=CODE_ROOT/'docs';folder.mkdir(exist_ok=True)
page=page.replace('dataset=benchmark','dataset='+ROOT.name).replace('../benchmark/outputs/','../'+ROOT.name+'/outputs/')
if ROOT.name=='pilot':
    notice='<article class="card"><h3>100题开发验证已完成</h3><p>9题原稿已修正并由三组对称重跑；原始记录完整归档。评分分歧已经按固定协议重新听音裁定，尚未经过独立人工校准。</p><div class="links"><a href="PILOT_REPORT.md">查看验证报告</a><a href="FULL_RUN_POLICY.md">查看评分协议</a></div></article>'
    page=page.replace('<h2>如何理解这次测评</h2>',notice+'<h2>如何理解这次测评</h2>')
(folder/'index.html').write_text(page.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')),'utf-8')
rows=['| 系统 | 类别 | 通过 / 总数 | 通过率 | 六维均分 |','|---|---|---:|---:|---:|']
for s in summary['systems']:
    pct='待裁定' if s['strict_pass_rate'] is None else f"{s['strict_pass_rate']:.1%}";mean='NA' if s['overall_dimension_mean'] is None else f"{s['overall_dimension_mean']:.2f}"
    rows.append(f"| {s['system_id']} | {s['category']} | {s['passed_count']} / {s['planned']} | {pct} | {mean} |")
(folder/'RESULTS.md').write_text('# v0.4 实测结果\n\n'+('开发验证集' if summary['split']=='development' else '正式测试集')+'，统计时间 '+summary['generated_at']+'。\n\n'+'\n'.join(rows)+'\n\n任务通过采用最终裁定，六维质量保留首次听音评分并单独报告。没有实际声音的失败记录没有听音均分。完整逐题证据位于各数据目录的 runs，原始 v0.3 保持不变。\n','utf-8')
print(json.dumps({'html':str(folder/'index.html'),'results':str(folder/'RESULTS.md'),'split':summary['split']},ensure_ascii=False))
